import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

// CuTe is imported only inside the named implementation namespace.

namespace cute_conv2d_detail {
using namespace cute;
enum : int {
    kInChannels = 3,
    kOutChannels = 96,
    kKernel = 11,
    kStride = 4,
    kPadding = 2,
    kTileH = 8,
    kTileW = 8,
    kTileOC = 32,
    kInputTileH = (kTileH - 1) * kStride + kKernel,
    kInputTileW = (kTileW - 1) * kStride + kKernel,
    kReduction = kInChannels * kKernel * kKernel,
};
} // namespace cute_conv2d_detail

namespace cute_conv2d_detail {
__global__ void cute_conv2d_kernel(
    float const* __restrict__ x,
    float const* __restrict__ weight,
    float const* __restrict__ bias,
    float* __restrict__ output,
    int N,
    int H,
    int W,
    int OH,
    int OW)
{
    extern __shared__ float smem[];
    float* smem_weight = smem;
    float* smem_input =
        smem_weight + kTileOC * kReduction;
    int tid = threadIdx.x;

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(N, kInChannels, H, W),
        make_stride(
            kInChannels * H * W,
            H * W,
            W,
            Int<1>{}));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(kOutChannels, kInChannels, kKernel, kKernel),
        make_stride(
            kInChannels * kKernel * kKernel,
            kKernel * kKernel,
            kKernel,
            Int<1>{}));

    auto gY = make_tensor(
        make_gmem_ptr(output),
        make_shape(N, kOutChannels, OH, OW),
        make_stride(
            kOutChannels * OH * OW,
            OH * OW,
            OW,
            Int<1>{}));

    auto sW = make_tensor(
        make_smem_ptr(smem_weight),
        make_shape(kTileOC, kReduction),
        make_stride(kReduction, Int<1>{}));

    auto sX = make_tensor(
        make_smem_ptr(smem_input),
        make_shape(kInChannels, kInputTileH, kInputTileW),
        make_stride(
            kInputTileH * kInputTileW,
            kInputTileW,
            Int<1>{}));

    int n = static_cast<int>(blockIdx.z);
    int tiles_w = (OW + kTileW - 1) / kTileW;
    int oc_tile = static_cast<int>(blockIdx.x) / tiles_w;
    int ow_tile = static_cast<int>(blockIdx.x) % tiles_w;
    int base_oh = static_cast<int>(blockIdx.y) * kTileH;
    int base_ow = ow_tile * kTileW;

    int weight_count = kTileOC * kReduction;
    for (int linear = tid; linear < weight_count; linear += blockDim.x) {
        int local_oc = linear / kReduction;
        int reduction_idx = linear - local_oc * kReduction;

        int c = reduction_idx / (kKernel * kKernel);
        int rem = reduction_idx - c * kKernel * kKernel;
        int ky = rem / kKernel;
        int kx = rem - ky * kKernel;

        int global_oc = local_oc + oc_tile * kTileOC;
        if (global_oc < kOutChannels) {
            sW(local_oc, reduction_idx) = gW(global_oc, c, ky, kx);
        } else {
            sW(local_oc, reduction_idx) = 0.0f;
        }
    }

    int input_tile_count =
        kInChannels * kInputTileH * kInputTileW;

    for (int linear = tid; linear < input_tile_count; linear += blockDim.x) {
        int c = linear / (kInputTileH * kInputTileW);
        int rem = linear - c * kInputTileH * kInputTileW;
        int iy = rem / kInputTileW;
        int ix = rem - iy * kInputTileW;

        int global_iy = base_oh * kStride + iy - kPadding;
        int global_ix = base_ow * kStride + ix - kPadding;

        if (n < N &&
            global_iy >= 0 && global_iy < H &&
            global_ix >= 0 && global_ix < W) {
            sX(c, iy, ix) = gX(n, c, global_iy, global_ix);
        } else {
            sX(c, iy, ix) = 0.0f;
        }
    }

    __syncthreads();

    // Increase output-channel reuse per staged input tile: each CTA
    // computes an 8x8 spatial tile for 32 output channels.
    int spatial_idx = tid & 63;
    int oc_group = tid >> 6;
    int local_oh = spatial_idx / kTileW;
    int local_ow = spatial_idx - local_oh * kTileW;
    int out_oh = base_oh + local_oh;
    int out_ow = base_ow + local_ow;
    bool valid = (out_oh < OH && out_ow < OW);
    int local_oc_base = oc_group * 8;
    int global_oc_base = oc_tile * kTileOC + local_oc_base;
    float acc[8];
#pragma unroll
    for (int j = 0; j < 8; ++j) {
        int global_oc = global_oc_base + j;
        acc[j] = (valid && global_oc < kOutChannels)
            ? bias[global_oc]
            : 0.0f;
    }
#pragma unroll
    for (int c = 0; c < kInChannels; ++c) {
#pragma unroll
        for (int ky = 0; ky < kKernel; ++ky) {
            int sy = local_oh * kStride + ky;
#pragma unroll
            for (int kx = 0; kx < kKernel; ++kx) {
                int sx = local_ow * kStride + kx;
                int reduction_idx =
                    c * kKernel * kKernel + ky * kKernel + kx;
                float v = valid ? sX(c, sy, sx) : 0.0f;
#pragma unroll
                for (int j = 0; j < 8; ++j) {
                    int local_oc = local_oc_base + j;
                    int global_oc = global_oc_base + j;
                    if (global_oc < kOutChannels) {
                        acc[j] += v * sW(local_oc, reduction_idx);
                    }
                }
            }
        }
    }
    if (valid) {
#pragma unroll
        for (int j = 0; j < 8; ++j) {
            int global_oc = global_oc_base + j;
            if (global_oc < kOutChannels) {
                gY(n, global_oc, out_oh, out_ow) = acc[j];
            }
        }
    }
} // cute_conv2d_kernel

} // namespace cute_conv2d_detail


using namespace cute_conv2d_detail;
torch::Tensor cute_conv2d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    TORCH_CHECK(x.size(1) == kInChannels, "expected 3 input channels");
    TORCH_CHECK(weight.size(0) == kOutChannels, "expected 96 output channels");
    TORCH_CHECK(weight.size(1) == kInChannels, "invalid weight channels");
    TORCH_CHECK(weight.size(2) == kKernel, "invalid kernel height");
    TORCH_CHECK(weight.size(3) == kKernel, "invalid kernel width");
    TORCH_CHECK(bias.size(0) == kOutChannels, "invalid bias size");

    auto x_c = x.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();

    int N = static_cast<int>(x_c.size(0));
    int H = static_cast<int>(x_c.size(2));
    int W = static_cast<int>(x_c.size(3));

    int OH = (H + 2 * kPadding - kKernel) / kStride + 1;
    int OW = (W + 2 * kPadding - kKernel) / kStride + 1;

    auto output = torch::empty(
        {N, kOutChannels, OH, OW},
        x_c.options());

    int tiles_h = (OH + kTileH - 1) / kTileH;
    int tiles_w = (OW + kTileW - 1) / kTileW;
    int tiles_oc = (kOutChannels + kTileOC - 1) / kTileOC;
    dim3 block(256);
    dim3 grid(
        tiles_w * tiles_oc,
        tiles_h,
        N);
    cudaStream_t stream =
        c10::cuda::getCurrentCUDAStream().stream();
    const size_t shared_bytes =
        static_cast<size_t>(
            kTileOC * kReduction +
            kInChannels * kInputTileH * kInputTileW) *
        sizeof(float);
    // The requested shared memory is larger than the usual 48 KiB
    // default dynamic shared-memory limit.
    cudaError_t attr_status = cudaFuncSetAttribute(
        (const void*)cute_conv2d_detail::cute_conv2d_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        static_cast<int>(shared_bytes));
    TORCH_CHECK(
        attr_status == cudaSuccess,
        "Could not configure dynamic shared memory: ",
        cudaGetErrorString(attr_status));
    cute_conv2d_detail::cute_conv2d_kernel
        <<<grid, block, shared_bytes, stream>>>(
            x_c.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            output.data_ptr<float>(),
            N,
            H,
            W,
            OH,
            OW);
    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CuTe convolution kernel launch failed");
    return output;

}
"""


cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
        )
        self._ext = cute_ext

    def forward(self, x):
        return self._ext.cute_conv2d(
            x,
            self.conv1.weight,
            self.conv1.bias,
        )

